class Solution:
    def minNumberOperations(self, target: List[int]) -> int:
        n = len(target)
        cur = [0] * n
        ops = 0
        while cur != target:
            i = 0
            while i < n and cur[i] == target[i]:
                i += 1
            j = i
            while j + 1 < n and cur[j + 1] < target[j + 1]:
                j += 1
            for k in range(i, j + 1):
                cur[k] += 1
            ops += 1
        return ops

