class Solution {
    public int minNumberOperations(int[] target) {
        int n = target.length;
        int[] cur = new int[n];
        int ops = 0;
        while (!java.util.Arrays.equals(cur, target)) {
            int i = 0;
            while (i < n && cur[i] == target[i]) i++;
            int j = i;
            while (j + 1 < n && cur[j + 1] < target[j + 1]) j++;
            for (int k = i; k <= j; k++) cur[k]++;
            ops++;
        }
        return ops;
    }
}

