class Solution {
    public int minNumberOperations(int[] target) {
        return solve(target, 0, target.length - 1, 0);
    }
    private int solve(int[] t, int l, int r, int base) {
        if (l > r) return 0;
        int m = l;
        for (int i = l + 1; i <= r; i++) if (t[i] < t[m]) m = i;
        int cost = t[m] - base;
        cost += solve(t, l, m - 1, t[m]);
        cost += solve(t, m + 1, r, t[m]);
        return cost;
    }
}

